-- Seed additional daily questions from daily_questions_202607171945.csv
INSERT INTO daily_questions (
    id,
    interest_id,
    question_text,
    question_level,
    empathy_guide,
    hint_guide,
    leading_question_guide
)
VALUES
  (661, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '여러 나라를 도는 여행과 한 곳에 머무는 여행 중 뭐가 더 마음이 가나요?', 1, '여행에서 중요한 건 사람마다 달라요.', '경험의 폭과 한 곳의 깊은 여유, 뭘 원하나요?', '그 스타일로 여행 가본 적 있어요?'),
  (662, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '전액 지원 세계 여행과 현금 4천만 원 중 뭐가 더 마음이 가나요?', 1, '경험과 현금 사이에서 고민하는 건 흔한 일이에요.', '돈의 자유와 특별한 경험, 뭘 원하나요?', '그런 상황이면 실제로도 그렇게 할 것 같아요?'),
  (663, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '손에 남는 선물과 마음에 남는 경험 중 뭐가 더 기억에 남나요?', 1, '선물에서 소중히 여기는 건 사람마다 달라요.', '손에 남는 물건과 마음에 남는 추억 중 뭘 원하나요?', '그런 선물 받아본 적 있어요?'),
  (664, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '도시의 작은 아파트와 시골의 넓은 집 중 뭐가 더 마음이 가나요?', 1, '살고 싶은 공간은 사람마다 다르게 그려져요.', '편리한 접근성과 넉넉한 공간 중 뭘 원하나요?', '그런 곳에서 살아본 적 있어요?'),
  (665, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '인터넷 없이 사는 것과 냉난방 없이 사는 것 중 뭐가 더 나은가요?', 1, '둘 다 없으면 답답한 것들이라 고민되죠.', '연결의 편리함과 몸의 쾌적함, 뭘 포기하기 어려운가요?', '그거 없이 며칠 지내본 적 있어요?'),
  (666, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '번화한 도시와 고요한 숲속 중 뭐가 더 끌리나요?', 1, '도시의 활기와 자연의 고요함, 둘 다 매력적이죠.', '편리한 분주함과 조용한 여유, 뭐가 필요한가요?', '요즘 그런 곳이 그리워요?'),
  (667, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '작은 도시에서 사는 것과 대도시에서 사는 것 중 뭐가 더 나에게 맞나요?', 1, '조용한 삶과 분주한 삶, 둘 다 나름의 매력이 있죠.', '여유로운 속도와 다채로운 자극, 뭐가 편한가요?', '지금 사는 곳도 그 느낌이에요?'),
  (668, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '전기·인터넷 같은 기술을 포기하는 것과 영화·TV·책 같은 오락을 포기하는 것 중 뭐가 덜 아쉬운가요?', 1, '편리함과 즐거움, 둘 다 놓기 힘든 것들이죠.', '생활의 편리함과 이야기의 몰입, 뭘 포기하기 어려운가요?', '그거 없이 하루 보내본 적 있어요?'),
  (669, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '예술 없는 삶과 과학 없는 삶 중 뭐가 더 힘드나요?', 2, '둘 다 삶에 필요해서 고르기 어려워요.', '감성이 채워지나요 이성이 채워지나요?', '평소엔 어느 쪽을 더 자주 찾게 돼요?'),
  (670, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '단순하게 사는 것과 복잡해도 풍부하게 사는 것 중 뭐가 더 나다운가요?', 1, '간결함과 풍성함, 둘 다 매력적이라 고르기 쉽지 않죠.', '덜어내는 게 편한가요 아니면 채우는 게 즐거운가요?', '요즘 삶은 어느 쪽에 더 가까워요?'),
  (671, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '물건을 소유하는 삶과 경험을 쌓는 삶 중 뭐가 더 남나요?', 2, '소유와 경험, 둘 다 만족을 주지만 방식이 다르죠.', '손에 잡히는 게 중요한가요 아니면 기억에 남는 게 중요한가요?', '최근엔 뭘 더 많이 선택했어요?'),
  (672, (SELECT id FROM interests WHERE code = 'PREFERENCE'), '스트레스 없는 삶과 지루함 없는 삶 중 뭐가 더 끌리나요?', 1, '편안함과 자극, 둘 다 삶에 활력을 줘요.', '잔잔한 게 좋은가요 아니면 늘 새로운 게 좋은가요?', '요즘 나한테 더 부족한 쪽 같아요?'),
  (673, (SELECT id FROM interests WHERE code = 'EMOTION'), '아파도 감정을 그대로 느끼는 것과 부정적인 감정을 안 느끼는 것 중 뭐가 더 좋나요?', 2, '다 느낀다는 건 아파도 그만큼 진짜라는 뜻이에요.', '무뎌지는 편안함과 생생한 힘듦, 뭘 원하나요?', '요즘도 그렇게 다 느끼고 있어요?'),
  (674, (SELECT id FROM interests WHERE code = 'EMOTION'), '몸의 아픔을 못 느끼는 것과 마음의 아픔을 못 느끼는 것 중 뭐가 더 나은가요?', 2, '몸의 아픔과 마음의 아픔, 둘 다 없었으면 싶죠.', '몸을 지키는 감각과 마음을 지키는 감각, 뭘 지키나요?', '요즘 둘 중 뭐가 더 예민해져 있어요?'),
  (675, (SELECT id FROM interests WHERE code = 'EMOTION'), '감정을 강렬하게 느끼는 것과 잔잔하게 한결같이 느끼는 것 중 뭐가 더 나다운가요?', 2, '큰 기복도 잔잔함도 다 나름의 방식이에요.', '짜릿한 순간과 잔잔한 평온, 뭐가 편안한가요?', '지금 내 감정 기복은 어느 쪽에 가까워요?'),
  (676, (SELECT id FROM interests WHERE code = 'EMOTION'), '내 감정을 다스리는 것과 생각을 다스리는 것 중 뭐가 더 하고 싶나요?', 2, '감정도 생각도 다스리고 싶은 마음은 자연스러워요.', '더 힘든 건 감정인가요, 생각인가요?', '요즘 나를 더 흔드는 건 어느 쪽이에요?'),
  (677, (SELECT id FROM interests WHERE code = 'EMOTION'), '평생 남을 후회와 한순간의 창피함 중 뭐가 더 두렵나요?', 2, '오래가는 후회와 순간의 창피함, 둘 다 피하고 싶죠.', '긴 시간의 무게와 짧은 순간의 강도, 뭐가 힘든가요?', '둘 중 어느 쪽을 더 피하고 싶어요?'),
  (678, (SELECT id FROM interests WHERE code = 'EMOTION'), '사랑을 못 느끼는 것과 두려움을 못 느끼는 것 중 뭐가 덜 두렵나요?', 2, '감정 하나를 잃는 상상, 둘 다 쉽지 않죠.', '설렘을 잃는 것과 조심성을 잃는 것, 뭐가 두려운가요?', '둘 중 어느 감정을 잃는 게 더 무서워요?'),
  (679, (SELECT id FROM interests WHERE code = 'EMOTION'), '감정을 못 드러내는 것과 못 숨기는 것 중 뭐가 덜 힘든가요?', 2, '표현 못 하는 답답함과 못 숨기는 부담, 둘 다 힘겹죠.', '속으로 삭이는 것과 다 드러나는 것, 뭐가 견디기 힘든가요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (680, (SELECT id FROM interests WHERE code = 'EMOTION'), '내 감정을 완전히 다스리는 능력과 타인의 감정을 읽는 능력 중 뭐가 더 갖고 싶나요?', 2, '나를 아는 것과 남을 아는 것, 둘 다 관계에서 중요한 힘이에요.', '안으로 향하는 힘인가요, 밖으로 향하는 힘인가요?', '요즘 어느 쪽이 더 힘들어요?'),
  (681, (SELECT id FROM interests WHERE code = 'ROUTINE'), '복잡해도 빠른 출근길과 여유롭지만 긴 출근길 중 뭐가 더 나은가요?', 1, '출퇴근길 피로는 하루 기분을 크게 좌우해요.', '몸의 피로와 시간의 여유 중 뭘 아끼고 싶나요?', '요즘 출근길은 어느 쪽에 가까워요?'),
  (682, (SELECT id FROM interests WHERE code = 'ROUTINE'), '10분 늦는 것과 20분 일찍 오는 것 중 뭐가 더 편한가요?', 1, '시간 습관은 몸에 배어 쉽게 안 바뀌어요.', '여유로운 기다림과 아슬아슬한 맞춤, 뭐가 편한가요?', '평소에도 그 습관 그대로예요?'),
  (683, (SELECT id FROM interests WHERE code = 'ROUTINE'), '몸의 컨디션과 마음의 안정 중 뭐가 더 먼저인가요?', 2, '몸과 마음 둘 다 중요해서 우선순위를 정하기 쉽지 않아요.', '겉으로 보이는 컨디션과 마음속 안정감, 뭘 챙기나요?', '요즘엔 어느 쪽을 더 못 챙기고 있어요?'),
  (684, (SELECT id FROM interests WHERE code = 'ROUTINE'), '당장 소원 하나와 10년 후 소원 세 개 중 뭐가 더 좋은가요?', 1, '당장의 만족과 나중의 큰 보상, 누구나 고민해봤죠.', '지금의 확실함과 나중의 풍성함, 뭘 기다릴 수 있나요?', '평소에도 그런 선택 자주 해요?'),
  (685, (SELECT id FROM interests WHERE code = 'ROUTINE'), '많은 시간과 많은 에너지 중 뭐가 더 좋은가요?', 2, '시간도 에너지도 부족한 요즘, 둘 다 갖고 싶죠.', '쓸 시간과 쓸 힘, 지금 더 부족한 건 뭔가요?', '요즘 둘 중에 뭐가 더 간절해요?'),
  (686, (SELECT id FROM interests WHERE code = 'ROUTINE'), '언제 죽을지와 어떻게 죽을지 중 뭐가 더 궁금한가요?', 2, '죽음에 대한 고민, 누구나 한 번쯤 해요.', '시간이 궁금한가요 아니면 방식이 궁금한가요?', '그런 생각, 요즘도 가끔 해요?'),
  (687, (SELECT id FROM interests WHERE code = 'ROUTINE'), '잠들지 못하는 것과 깨지 못하는 것 중 뭐가 더 두렵나요?', 2, '둘 다 상상만 해도 아찔한 상황이라 고르기 어려운 질문이에요.', '끝없는 깨어 있음이 무서운가요 아니면 끝없는 잠이 무서운가요?', '상상만 해도 소름 돋지 않아요?'),
  (688, (SELECT id FROM interests WHERE code = 'ROUTINE'), '위험해도 나을 가능성에 도전하는 것과 안전하게 지내는 것 중 뭐가 더 나은가요?', 2, '희망과 확실함 사이의 선택, 상상만으로도 무거운 고민이에요.', '가능성에 걸어보고 싶은가요 아니면 확실한 시간이 더 소중한가요?', '그런 선택, 실제로 해본 적 있어요?'),
  (689, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '친구 한 명을 잃는 것과 나머지 모든 친구를 잃는 것 중 뭐가 더 아픈가요?', 2, '누군가를 잃는다는 상상만으로도 마음이 무거워요.', '깊은 한 사람과 여러 사람, 뭘 지키고 싶나요?', '지금 옆에 그런 친구 있어요?'),
  (690, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '명절엔 가족과 있는 것과 친구들과 있는 것 중 뭐가 더 편한가요?', 1, '명절을 누구와 보내고 싶은지는 관계 우선순위를 보여줘요.', '가족의 편안함과 친구의 자유로운 즐거움, 뭘 원하나요?', '이번 명절엔 어느 쪽이었어요?'),
  (691, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '두려움의 대상과 사랑받는 사람 중 누가 더 되고 싶나요?', 2, '영향력을 갖는 방식은 사람마다 달라요.', '힘으로 얻는 영향력과 마음으로 얻는 신뢰, 뭘 원하나요?', '주변에 그런 사람 있어요?'),
  (692, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '친구들에게 인정받는 것과 부모님께 인정받는 것 중 뭐가 더 중요한가요?', 2, '누구의 인정을 바라는지는 관계에 따라 달라요.', '가족의 시선과 친구의 시선, 뭐가 무겁게 다가오나요?', '요즘은 어느 쪽 시선이 더 신경쓰여요?'),
  (693, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '가족의 마음과 대중의 평가 중 뭐가 더 중요한가요?', 2, '누구의 인정이 소중한지는 답하기 어려워요.', '가까운 사람의 마음과 세상의 평판, 뭘 중요히 보나요?', '최근에 그걸 느낀 순간 있었어요?'),
  (694, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '좋은 친구가 많지만 가난한 삶과 친구 없이 부유한 삶 중 뭐가 더 괜찮은가요?', 2, '관계와 물질, 둘 다 삶에서 중요해요.', '곁에 있는 사람들과 경제적 여유 중 뭘 포기하기 힘든가요?', '지금 삶은 어느 쪽에 더 가까워요?'),
  (695, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '5년을 혼자 지내는 것과 늘 사람들과 붙어 지내는 것 중 뭐가 더 편안한가요?', 1, '혼자만의 시간과 사람들과의 연결, 둘 다 필요해요.', '온전한 고요함과 끊이지 않는 관계, 뭐가 견디기 힘든가요?', '지금 나는 어느 쪽이 더 필요해요?'),
  (696, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '삶에서 일과 가족 중 뭐가 더 우선인가요?', 2, '일과 가족, 둘 다 놓칠 수 없는 삶의 중심이에요.', '성취를 향한 몰입과 곁을 지키는 시간, 뭘 원하나요?', '요즘 시간은 어느 쪽에 더 많이 쓰고 있어요?'),
  (697, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '연애는 SNS에 공개하는 것과 비공개로 두는 것 중 뭐가 더 편한가요?', 1, '공개하고 싶은 마음도 지키고 싶은 마음도 자연스러워요.', '사람들과 나누는 기쁨과 둘만의 온전한 시간, 뭘 원하나요?', '지금 연애도 그 방식이에요?'),
  (698, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '친구가 내 실수를 솔직하게 말해주는 것과 그냥 넘어가 주는 것 중 뭐가 더 나은가요?', 1, '솔직한 피드백과 배려, 둘 다 우정에서 바랄 수 있어요.', '따끔한 조언과 마음 편하게 가만히 있는 것, 뭘 원하나요?', '친구가 그렇게 해준 적 있어요?'),
  (699, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '무모한 결정에도 무조건 지지해주는 것과 말려주는 것 중 뭐가 더 좋은가요?', 1, '지지받고 싶은 마음도 붙잡아주길 바라는 마음도 자연스러워요.', '무조건적인 응원과 현실적인 조언 중 뭘 원하나요?', '그런 순간에 친구가 어떻게 해줬어요?'),
  (700, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '너무 솔직해서 상처받는 친구 그룹과 불편한 주제를 피하는 친구 그룹 중 뭐가 더 좋은가요?', 2, '솔직함과 편안함 사이에서 고민하는 건 자연스러운 일이에요.', '아파도 진짜인 대화와 부드럽게 겉도는 대화, 뭘 원하나요?', '지금 내 친구들은 어느 쪽에 가까워요?'),
  (701, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '모임을 이끄는 것과 따르는 것 중 어디에 더 가까운 편인가요?', 1, '이끄는 역할과 따르는 역할, 둘 다 모임에서 필요한 자리예요.', '정하는 부담과 따르는 편안함, 뭘 원하나요?', '평소 모임에서는 주로 어떤 역할이에요?'),
  (702, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '모든 게 공유되는 세상과 모든 게 비밀인 세상 중 뭐가 더 편안한가요?', 2, '연결과 프라이버시 사이 균형은 늘 고민이에요.', '다 드러내도 편한가요, 감춰야 편한가요?', '요즘 SNS는 그중 어느 쪽에 더 가까워요?'),
  (703, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '늘 들어주는 역할과 늘 털어놓는 역할 중 뭐가 더 편한가요?', 2, '들어주는 것도 털어놓는 것도 다 필요한 몫이에요.', '요즘 나는 주로 어떤 역할을 맡고 있나요?', '요즘도 계속 그 역할이에요?'),
  (704, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '순간의 행복을 주는 힘과 오래가는 관계를 만드는 힘 중 뭐가 더 갖고 싶나요?', 2, '즉각적인 기쁨과 오래가는 신뢰 다 소중해요.', '순간의 만족과 단단함, 뭐가 남는 관계인가요?', '지금 내 관계는 어느 쪽에 더 기울어져 있어요?'),
  (705, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '10억을 준다면, 절친을 배신하는 것과 의리를 지키는 것 중 뭐가 더 끌리나요?', 2, '큰돈 앞에서 흔들리는 마음은 복잡해요.', '돈으로 살 수 없는 게 뭔지 생각해볼까요?', '실제로 그런 상황이면 어떨 것 같아요?'),
  (706, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '인성은 아쉽지만 능력 좋은 동료와 인성 좋지만 인성은 아쉬운 동료 중 누구와 함께하고 싶나요?', 2, '실력과 인성 사이 고민은 누구나 공감할 거예요.', '매일 부대낄 사람이라면 뭐가 중요한가요?', '지금 팀에 그런 동료 있어요?'),
  (707, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '로또에 당첨되면 누구에게까지 알릴 건가요?', 2, '큰돈 앞에서 어디까지 나눌지 고민돼요.', '그 비밀을 혼자 감당할 자신 있나요?', '그 얘기 누구한테 제일 먼저 하고 싶어요?'),
  (708, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '힘든 순간에 곁을 지키는 것과 좋은 순간을 축하하는 것 중 더 중요한 건 뭐라고 생각하나요?', 2, '힘든 순간과 기쁜 순간, 곁에 있어주고픈 마음은 같아요.', '위로와 축하 중 나에게 더 자연스러운 건 뭔가요?', '친구들 사이에서 나는 주로 어느 쪽이에요?'),
  (709, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '늘 웃게 해주는 친구와 생각하게 만드는 친구 중 누가 더 끌리나요?', 1, '재미와 깊이, 친구에게 바라는 게 다를 수 있어요.', '가벼운 즐거움과 묵직한 자극, 뭐가 끌리나요?', '지금 곁에 그런 친구 있어요?'),
  (710, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '어려울 때 먼저 떠오르는 친구와 기쁠 때 먼저 생각나는 친구 중 어느 쪽이 되고 싶나요?', 1, '어떤 순간에 떠오르는 사람이고 싶은지는 다 달라요.', '힘들 때 의지와 기쁠 때 동행, 뭐가 더 끌리나요?', '요즘 나는 어느 쪽에 더 가까워요?'),
  (711, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '관계를 정리할 때 주로 어떻게 하는 편인가요?', 2, '관계를 정리하는 방식은 사람마다 다 달라요.', '가만히 있는 것과 솔직하게 정리하는 것, 내 마음이 편한 쪽은 뭔가요?', '최근에 그렇게 정리해본 적 있어요?'),
  (712, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '편안한 우정과 나를 성장시키는 우정 중 뭐가 더 끌리나요?', 2, '편안함과 성장, 둘 다 우정에서 얻고 싶은 가치예요.', '지금 나에게 필요한 건 자극인가요, 안정인가요?', '지금 우정은 어느 쪽에 더 가까워요?'),
  (713, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '널리 얕게 사랑받는 것과 미움받아도 깊은 관계 하나 중 뭐가 더 소중한가요?', 2, '넓은 호감과 깊은 관계, 사람마다 원하는 쪽이 달라요.', '폭넓은 인정과 단 하나의 진짜 관계, 뭐가 힘이 되나요?', '지금 관계는 어느 쪽에 더 가까워요?'),
  (714, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '아무 문제 없는 세상과 내가 다스리는 세상 중 뭐가 더 좋은가요?', 2, '평온한 세상과 권력을 쥔 세상, 둘 다 매력적이죠.', '모두의 편안함과 내가 다 결정하는 것, 뭐가 더 끌리나요?', '그런 상상, 재밌지 않아요?'),
  (715, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '권위형 리더와 솔선수범형 리더 중 어느 쪽에 더 가깝나요?', 2, '리더십의 방식에 대한 고민은 누구나 한 번쯤 하게 돼요.', '행동으로 보여주는 게 중요한가요 아니면 확실한 힘이 중요한가요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (716, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '남의 운명을 좌우하는 것과 내 삶을 내 뜻대로 하는 것 중 뭐가 더 좋나요?', 2, '나를 위한 힘과 남을 위한 힘, 무게가 다르죠.', '내 삶의 주인이 되고 싶은가요 아니면 더 큰 영향력을 갖고 싶은가요?', '요즘 그런 고민 해본 적 있어요?'),
  (717, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '내 뜻대로 하는 힘과 모두에게 믿음받는 것 중 뭐가 더 나은가요?', 2, '힘과 신뢰, 둘 다 리더에게 필요해 보이지만 다른 길이에요.', '장악하는 힘이 중요한가요 아니면 마음을 얻는 게 중요한가요?', '지금 나는 어느 쪽을 더 원해요?'),
  (718, (SELECT id FROM interests WHERE code = 'RELATIONSHIP'), '친구의 착각을 바로잡는 것과 관계를 위해 그냥 두는 것 중 뭐가 더 맞나요?', 1, '굳이 말해야 할지 고민되는 순간, 친구를 아끼기 때문이겠죠.', '지금의 편안함이 중요한가요 아니면 바로잡는 게 중요한가요?', '최근에 그런 상황 있었어요?'),
  (719, (SELECT id FROM interests WHERE code = 'LOVE'), '연애할 때 외모와 유머 감각 중 뭐가 더 중요한가요?', 1, '끌리는 포인트는 사람마다 다르고, 그게 자연스러운 거예요.', '첫인상과 오래 갈수록 좋아지는 매력, 뭐가 중요한가요?', '요즘 나는 어느 쪽에 더 끌려요?'),
  (720, (SELECT id FROM interests WHERE code = 'LOVE'), '사소한 기념일까지 챙기는 것과 중요한 날만 챙기는 것 중 뭐가 더 편한가요?', 1, '챙기는 방식이 다르다고 마음의 크기가 다른 건 아니에요.', '이벤트 빈도와 담긴 정성 중 뭐가 중요한가요?', '지금 관계에서도 그 방식이에요?'),
  (721, (SELECT id FROM interests WHERE code = 'LOVE'), '빠른 답장과 느려도 정성 담긴 답장 중 뭐가 더 좋은가요?', 1, '연락에 예민해지는 건 마음을 쓴다는 뜻이에요.', '속도와 정성 중 나에게 안정감을 주는 쪽을 떠올려봐요.', '요즘도 그 방식이 편해요?'),
  (722, (SELECT id FROM interests WHERE code = 'LOVE'), '자주 삐지지만 금방 푸는 애인과 가끔 삐지지만 오래가는 애인 중 누가 더 힘든가요?', 1, '감정 기복을 견디는 정도는 사람마다 달라요.', '지치는 빈도와 회복 시간 중 뭐가 크게 느껴지나요?', '그런 상황, 최근에 있었어요?'),
  (723, (SELECT id FROM interests WHERE code = 'LOVE'), '전 애인과 밤새 술 마시는 것과 이성 친구와 단둘이 여행 가는 것 중 뭐가 더 불안한가요?', 2, '이런 상황에 불안해지는 건 자연스러운 감정이에요.', '관계의 역사와 물리적 거리, 뭐가 신경 쓰이나요?', '그런 상황이면 실제로 불안할 것 같아요?'),
  (724, (SELECT id FROM interests WHERE code = 'LOVE'), '연인과 유머 코드가 맞는 것과 사회 이슈에 화나는 포인트가 비슷한 것 중 뭐가 더 중요한가요?', 2, '잘 맞는 부분이 다르다고 관계가 얕은 건 아니에요.', '즐거움과 세상 보는 눈, 뭘 더 우선하나요?', '그 기준, 지금 연애에도 적용돼요?'),
  (725, (SELECT id FROM interests WHERE code = 'LOVE'), '연락이 끊기는 애인과 술을 자주 마시는 애인 중 누가 더 아픈가요?', 2, '빈도보다 믿음이 흔들리는 순간이 더 아파요.', '잦은 빈도와 신뢰 붕괴 중 뭐가 크게 다가오나요?', '그런 순간, 겪어본 적 있어요?'),
  (726, (SELECT id FROM interests WHERE code = 'LOVE'), '매일 만나고 싶어 하는 애인과 만날 시간 잡기 어려운 애인 중 누가 더 좋은가요?', 1, '둘 다 아쉬운 부분이 있어서 고르기 애매한 질문이에요.', '시간의 양과 다른 관계, 뭘 더 중요히 보나요?', '지금 연애도 그런 느낌이에요?'),
  (727, (SELECT id FROM interests WHERE code = 'LOVE'), '사랑을 찾는 것과 큰돈을 찾는 것 중 뭐가 더 중요한가요?', 2, '사랑과 돈, 둘 다 포기하기 어려운 가치예요.', '마음을 채우는 것과 삶을 안정시키는 것, 뭘 원하나요?', '요즘 둘 중 뭐가 더 간절해요?'),
  (728, (SELECT id FROM interests WHERE code = 'LOVE'), '나쁜 연애를 지속하는 삶과 평생 혼자 지내는 삶 중, 어떤 쪽이 더 낫다고 생각하시나요?', 2, '이런 상상만으로도 마음이 복잡해지는 게 당연해요.', '관계의 불안정함과 혼자만의 자유, 뭘 더 견디기 힘든가요?', '그런 상상, 해본 적 있어요?'),
  (729, (SELECT id FROM interests WHERE code = 'LOVE'), '질투 많은 연인과 질투가 없는 연인 중 누가 더 좋은가요?', 2, '관심받는 것과 동등한 것, 둘 다 관계에서 중요한 부분이에요.', '넘치는 애정과 균형 잡힌 신뢰 중 뭘 원하나요?', '지금 연애는 어느 쪽에 더 가까워요?'),
  (730, (SELECT id FROM interests WHERE code = 'LOVE'), '사랑은 말로 표현하는 것과 행동으로 보여주는 것 중 뭐가 더 중요하다고 생각하나요?', 1, '사랑을 표현하는 방식은 사람마다 다르게 나타나요.', '직접적인 말과 은근한 행동, 뭐가 편안한가요?', '나는 보통 어느 쪽으로 표현해요?'),
  (731, (SELECT id FROM interests WHERE code = 'LOVE'), '말 없이도 알아채 주길 바라는 것과 명확히 말하는 것 중 뭐가 더 편한가요?', 1, '마음을 전하는 방식에 대한 기대는 사람마다 달라요.', '눈치껏 아는 배려와 분명히 말하는 확실함, 뭘 원하나요?', '그 기대, 최근에 안 채워진 적 있어요?'),
  (732, (SELECT id FROM interests WHERE code = 'LOVE'), '돈 많고 성격 나쁜 사람과 가난해도 착한 사람 중 누가 더 끌리나요?', 2, '조건과 마음 편함 사이 고민은 누구나 해봤을 거예요.', '결혼 생활을 채우는 건 잔고인가요, 태도인가요?', '그런 사람, 실제로 만나본 적 있어요?'),
  (733, (SELECT id FROM interests WHERE code = 'LOVE'), '지나간 첫사랑과 새로운 사랑 중 누가 더 끌리나요?', 2, '지나간 사랑에 대한 미련은 누구나 있어요.', '그리운 건 그 사람인가요, 그때 감정인가요?', '요즘 그런 마음 든 적 있어요?'),
  (734, (SELECT id FROM interests WHERE code = 'LOVE'), '무뚝뚝한 연인과 애정 표현이 과한 연인 중 누가 더 힘든가요?', 2, '표현의 양보다 내가 느끼는 편안함이 달라요.', '사랑을 확인하는 건 말인가요, 조용한 안정감인가요?', '지금 연애는 어느 쪽에 가까워요?'),
  (735, (SELECT id FROM interests WHERE code = 'LOVE'), '안 싸우는 무난한 연애와 부딪혀도 솔직한 연애 중 더 선호하는 것은 무엇인가요?', 2, '갈등 없는 평화도 솔직한 부딪힘도 관계의 한 모습이에요.', '더 중요한 건 편안함인가요, 솔직함인가요?', '지금 관계는 어느 쪽에 가까워요?'),
  (736, (SELECT id FROM interests WHERE code = 'LOVE'), '더 사랑받는 관계와 더 많이 사랑하는 관계 중 뭐가 더 좋은가요?', 2, '받는 사랑과 주는 사랑은 다른 방식으로 채워줘요.', '안정감을 주는 건 받는 쪽, 벅찬 건 주는 쪽인가요?', '지금까지 연애는 어느 쪽이었어요?'),
  (737, (SELECT id FROM interests WHERE code = 'LOVE'), '연인이 내 모든 걸 아는 것과 모르는 것 중 뭐가 더 좋은가요?', 2, '다 보여주고 싶은 마음도 지키고 싶은 마음도 자연스러워요.', '사생활은 위협인가요, 필요한 거리인가요?', '지금 연인과는 어느 쪽에 가까워요?'),
  (738, (SELECT id FROM interests WHERE code = 'LOVE'), '한 사람에게 깊이 이해받는 것과 여럿에게 사랑받는 것 중 뭐가 더 끌리나요?', 2, '깊은 이해와 넓은 사랑은 다르게 다가와요.', '나를 아는 한 사람과 좋아하는 여러 사람, 뭐가 든든한가요?', '지금 곁엔 어느 쪽이 더 많아요?'),
  (739, (SELECT id FROM interests WHERE code = 'LOVE'), '단짝 같은 연인과 매력적이지만 거리감이 있는 연인 중 누가 더 끌리나요?', 2, '설렘과 편안함 사이 고민은 누구나 해봤을 거예요.', '오래갈 관계엔 짜릿함인가요, 통하는 느낌인가요?', '지금 연애는 어느 쪽에 더 가까워요?'),
  (740, (SELECT id FROM interests WHERE code = 'LOVE'), '쉽게 용서하는 사람과 서운함을 같이 풀어가는 사람 중 누가 더 편한가요?', 2, '빠른 화해와 깊은 대화, 둘 다 관계를 지키는 다른 방식이에요.', '갈등이 빨리 지나가는 게 좋은가요 아니면 제대로 풀어가는 게 좋은가요?', '최근에 그런 상황 있었어요?'),
  (741, (SELECT id FROM interests WHERE code = 'LOVE'), '우연히 본 연인의 사생활을 솔직히 말하는 것과 모르는 척 넘어가는 것 중 뭐가 더 맞나요?', 2, '우연히 알게 된 사실을 어떻게 다룰지, 누구나 고민될 상황이에요.', '터놓고 말하는 게 편한가요 아니면 조용히 넘어가는 게 편한가요?', '그런 상황, 겪어본 적 있어요?'),
  (742, (SELECT id FROM interests WHERE code = 'LOVE'), '무너져가는 관계를 붙잡는 것과 정직하게 이별하는 것 중 뭐가 더 나은가요?', 2, '끝을 인정하는 것도, 붙잡는 것도 둘 다 사랑이 남아 있기 때문이겠죠.', '솔직한 끝맺음이 나은가요 아니면 남은 정을 지키는 게 나은가요?', '그런 순간, 겪어본 적 있어요?'),
  (743, (SELECT id FROM interests WHERE code = 'VALUES'), '대화를 주도하는 것과 경청하는 것 중 뭐가 더 편한가요?', 1, '대화 스타일엔 정답이 없고 상황마다 달라요.', '내가 편한 쪽과 상대가 편한 쪽을 떠올려봐요.', '평소 대화에서는 주로 어느 쪽이에요?'),
  (744, (SELECT id FROM interests WHERE code = 'VALUES'), '매번 늦는 사람과 재촉하는 사람 중 누가 더 미운가요?', 1, '둘 다 나름의 답답함이 있으니 고민되는 게 당연해요.', '약속 태도와 배려 중 뭐가 더 거슬리나요?', '주변에 그런 사람 있어요?'),
  (745, (SELECT id FROM interests WHERE code = 'VALUES'), '퇴사 못 하는 회사에서 월 600을 버는 것과 백수로 지내며 월 200을 받는 것 중 뭐가 더 나은가요?', 2, '돈과 자유 사이 고민은 누구에게나 어려워요.', '시간의 자유와 경제적 여유, 뭐가 급한가요?', '그런 상황이면 실제로 어떨 것 같아요?'),
  (746, (SELECT id FROM interests WHERE code = 'VALUES'), '연봉 2천에 매일 칼퇴근하는 것과 연봉 6천에 주 7일 일하는 것 중 뭐가 더 나에게 맞나요?', 2, '돈과 시간 둘 다 포기하기 어려운 가치예요.', '통장의 숫자와 나만의 시간, 뭐가 중요한가요?', '지금 일도 그 균형이에요?'),
  (747, (SELECT id FROM interests WHERE code = 'VALUES'), '칭찬받을 때와 싫은 소리를 들을 때 중 언제 일이 더 잘되나요?', 2, '동기부여 받는 방식은 사람마다 다르게 작동해요.', '인정받을 때와 자극받을 때, 언제 힘이 났는지 떠올려봐요.', '요즘 나는 어느 쪽으로 힘 받아요?'),
  (748, (SELECT id FROM interests WHERE code = 'VALUES'), '바쁘지만 성장하는 회사와 여유롭지만 성장 없는 회사 중 뭐가 더 나은가요?', 2, '완벽한 회사는 없으니 뭘 포기할지 고민돼요.', '지금 당장의 여유와 앞으로의 성장 중 뭘 우선하나요?', '지금 회사는 어느 쪽에 가까워요?'),
  (749, (SELECT id FROM interests WHERE code = 'VALUES'), '퇴사 날 아무도 모르게 조용히 나가는 것과 배웅받으며 화려하게 나가는 것 중 뭐가 더 하고 싶나요?', 1, '마무리하는 방식에도 그 사람의 성향이 묻어나요.', '조용한 홀가분함과 따뜻한 인사, 뭐가 어울리나요?', '실제로 퇴사한다면 어느 쪽일 것 같아요?'),
  (750, (SELECT id FROM interests WHERE code = 'VALUES'), '바빠서 지치는 것과 한가해서 지치는 것 중 뭐가 더 버거운가요?', 1, '바빠서든 심심해서든 지치는 건 다 힘들어요.', '몸이 지치는 것과 마음이 지치는 것, 뭐가 버거운가요?', '요즘 나는 어느 쪽에 더 가까워요?'),
  (751, (SELECT id FROM interests WHERE code = 'VALUES'), '배울 게 많은 상사와 편한 상사 중 누가 더 좋은가요?', 2, '편함과 배움 사이의 고민은 자연스러워요.', '지금의 편안함과 나중의 성장 중 뭘 우선하나요?', '지금 상사는 어느 쪽에 가까워요?'),
  (752, (SELECT id FROM interests WHERE code = 'VALUES'), '확실한 10억과 반반 확률의 50억 중 뭐가 더 나은가요?', 2, '확실함과 큰 가능성 사이 고민은 당연해요.', '확실한 결과와 위험한 기대값 중 뭐가 편한가요?', '그런 상황이면 실제로 뭘 고를 것 같아요?'),
  (753, (SELECT id FROM interests WHERE code = 'VALUES'), '남 밑에서 편하게 일하는 것과 내 사업을 하는 것 중 뭐가 더 나은가요?', 2, '안정과 도전 사이에서 흔들리는 건 자연스러운 고민이에요.', '편한 안정감과 내 것을 만드는 성취감, 뭘 원하나요?', '지금 일은 어느 쪽에 더 가까워요?'),
  (754, (SELECT id FROM interests WHERE code = 'VALUES'), '지금 당장 꿈의 직업과 매년 한 달 휴가 중 뭐가 더 나은가요?', 2, '지금의 만족과 꾸준한 여유 사이 고민은 당연해요.', '정기적인 쉼과 지금 이루는 꿈, 뭘 우선하나요?', '지금 일에서 더 아쉬운 쪽은 뭐예요?'),
  (755, (SELECT id FROM interests WHERE code = 'VALUES'), '존중하는 상사의 힘든 일과 무관심한 상사의 편한 일 중 뭐가 더 나은가요?', 2, '존중받는 것과 편한 것, 둘 다 포기하기 아까운 가치예요.', '압박 속 성장과 신경 안 쓰는 편안함, 뭘 원하나요?', '지금 일은 어느 쪽에 가까워요?'),
  (756, (SELECT id FROM interests WHERE code = 'VALUES'), '아무도 몰라주는 최고와 존경받는 평범함 중 뭐가 더 만족스러운가요?', 2, '인정받는 방식은 사람마다 다르게 느껴질 수 있어요.', '혼자 아는 실력과 남들이 알아주는 위치, 뭘 원하나요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (757, (SELECT id FROM interests WHERE code = 'VALUES'), '개인적인 삶의 성공과 커리어의 성공 중 뭐가 더 중요한가요?', 2, '둘 다 인생에서 중요해서 고르기 어려워요.', '곁의 행복과 사회적 성취, 뭘 우선하나요?', '지금 삶은 어느 쪽에 더 기울어져 있어요?'),
  (758, (SELECT id FROM interests WHERE code = 'VALUES'), '돈을 빚지는 것과 부탁을 빚지는 것 중 뭐가 더 부담스러운가요?', 1, '빚진 마음은 액수와 상관없이 무거워요.', '돈으로 갚을 부담과 마음으로 갚을 부담, 뭐가 무거운가요?', '최근에 그런 상황 있었어요?'),
  (759, (SELECT id FROM interests WHERE code = 'VALUES'), '당장의 빚과 평생 이어지는 소득 한계 중 뭐가 더 견디기 쉬운가요?', 2, '당장의 빚과 평생의 한계, 둘 다 부담스러운 선택이에요.', '일시적 어려움과 계속되는 제한, 뭐가 견디기 쉬운가요?', '지금 상황은 어느 쪽에 더 가까워요?'),
  (760, (SELECT id FROM interests WHERE code = 'VALUES'), '인간관계 없는 숲속의 고요함과 소란한 도시의 삶 중 뭐가 더 편안한가요?', 2, '고요함과 자극, 둘 다 나름의 매력이 있어요.', '혼자만의 평온함과 사람들 속 활기 중 뭘 원하나요?', '지금 사는 곳은 어느 쪽에 가까워요?'),
  (761, (SELECT id FROM interests WHERE code = 'VALUES'), '평생 다달이 받는 200만 원과 지금 당장의 5억 중 뭐가 더 든든한가요?', 2, '당장의 목돈과 꾸준한 안정, 둘 다 매력적인 선택이에요.', '평생의 안정감과 당장의 목돈, 뭘 원하나요?', '그런 상황이면 실제로 뭘 고를 것 같아요?'),
  (762, (SELECT id FROM interests WHERE code = 'VALUES'), '한 사람을 깊이 돕는 것과 백 명을 조금씩 돕는 것 중 뭐가 더 의미 있나요?', 2, '돕는 방식이 다를 뿐 둘 다 의미 있는 선택이에요.', '깊은 도움과 넓게 퍼지는 도움, 뭐가 가치 있나요?', '실제로 그렇게 도와본 적 있어요?'),
  (763, (SELECT id FROM interests WHERE code = 'VALUES'), '위안이 되는 거짓말과 불편한 진실 중 뭐가 더 나은가요?', 2, '진실과 위안 사이에서 흔들리는 건 자연스러운 일이에요.', '불편해도 아는 것과 편안하게 모르는 것, 뭘 원하나요?', '최근에 그런 순간 있었어요?'),
  (764, (SELECT id FROM interests WHERE code = 'VALUES'), '후회 없는 20년과 후회 많은 50년 중 뭐가 더 나은가요?', 2, '삶의 길이와 만족감을 재는 건 무거운 고민이에요.', '짧아도 후회 없는 삶과 길어도 아쉬운 삶, 뭘 원하나요?', '지금 삶은 어느 쪽에 더 가까워요?'),
  (765, (SELECT id FROM interests WHERE code = 'VALUES'), '짓지 않은 죄로 4년간 옥살이하는 것과 죄를 짓고 평생 불안하게 사는 것 중 뭐가 더 괴로운가요?', 2, '억울함과 죄책감, 둘 다 견디기 힘든 무게예요.', '정해진 억울함과 끝없는 불안, 뭐가 더 힘든가요?', '그런 상상, 해본 적 있어요?'),
  (766, (SELECT id FROM interests WHERE code = 'VALUES'), '10년만 버티고 은퇴하는 끔찍한 일과 평생 할 꿈의 직업 중 뭐가 더 나은가요?', 2, '당장의 만족과 나중의 자유, 둘 다 포기하기 아까운 가치예요.', '지금의 즐거움과 앞으로의 여유 중 뭘 우선하나요?', '지금 일은 어느 쪽에 가까워요?'),
  (767, (SELECT id FROM interests WHERE code = 'VALUES'), '보람 있게 열심히 일하는 삶과 편한 삶 중 뭐가 더 값진가요?', 2, '일의 의미와 편안함 사이에서 고민하는 건 당연해요.', '노력한 보람과 애쓰지 않는 편안함, 뭘 원하나요?', '지금 일은 어느 쪽에 더 가까워요?'),
  (768, (SELECT id FROM interests WHERE code = 'VALUES'), '거저 받은 20억과 스스로 일군 50억 중 뭐가 더 값진가요?', 2, '주어진 것과 이뤄낸 것, 둘 다 나름의 의미가 있어요.', '빠르게 얻는 여유와 스스로 만든 성취감, 뭘 원하나요?', '그런 상황이면 실제로 어떨 것 같아요?'),
  (769, (SELECT id FROM interests WHERE code = 'VALUES'), '세상 문제에 책임감을 느끼는 삶과 신경 쓰지 않고 즐기는 삶 중 뭐가 더 나다운가요?', 2, '책임감과 편안함 사이에서 갈등하는 건 당연한 일이에요.', '세상에 대한 책임감과 나를 위한 삶 중 뭘 우선하나요?', '요즘 나는 어느 쪽에 더 가까워요?'),
  (770, (SELECT id FROM interests WHERE code = 'VALUES'), '가장 인기 있는 사람과 가장 똑똑한 사람 중 누가 더 되고 싶나요?', 1, '인기와 실력, 둘 다 매력적이라 고민돼요.', '사람들과의 친밀함과 실력으로 얻는 인정, 뭘 원하나요?', '지금 나는 어느 쪽으로 더 알려져 있어요?'),
  (771, (SELECT id FROM interests WHERE code = 'VALUES'), '유명해지는 부와 조용한 부 중 뭐가 더 편안한가요?', 1, '관심을 받는 삶과 조용한 삶, 둘 다 나름의 장단점이 있어요.', '사람들의 관심과 조용한 자유 중 뭘 원하나요?', '그런 삶, 상상해본 적 있어요?'),
  (772, (SELECT id FROM interests WHERE code = 'VALUES'), '크게 이룬 것 없는 만족스러운 삶과 이루고도 불만족스러운 삶 중 뭐가 더 나은가요?', 2, '만족감과 성취, 둘 다 놓치기 아까운 가치예요.', '마음의 평온함과 눈에 보이는 성과 중 뭘 원하나요?', '지금 삶은 어느 쪽에 더 가까워요?'),
  (773, (SELECT id FROM interests WHERE code = 'VALUES'), '같은 월급이면 몸을 움직이는 일과 사무직 중 뭐가 더 마음이 가나요?', 1, '몸을 쓰는 일과 머리를 쓰는 일, 편한 쪽은 사람마다 달라요.', '앉아서 집중하기와 움직이며 만들기, 뭘 원하나요?', '지금 일은 어느 쪽에 가까워요?'),
  (774, (SELECT id FROM interests WHERE code = 'VALUES'), '노숙자를 돕는 일과 아이들을 가르치는 일 중 뭐가 더 마음이 가나요?', 2, '돕고 싶은 마음은 같아도 끌리는 방식은 다를 수 있어요.', '당장의 어려움과 미래를 바꾸는 것, 뭘 중요히 보나요?', '그런 경험, 해본 적 있어요?'),
  (775, (SELECT id FROM interests WHERE code = 'VALUES'), '짧더라도 부유한 삶과 길고 가난한 삶 중 뭐가 더 나에게 맞나요?', 2, '삶의 길이와 여유, 둘 다 쉽게 포기할 수 없는 가치예요.', '짧아도 풍족한 삶과 길지만 빠듯한 삶, 뭘 원하나요?', '그런 상황이면 실제로 어떨 것 같아요?'),
  (776, (SELECT id FROM interests WHERE code = 'VALUES'), '자유의지로 선택한 결과와 정해진 운명 중 뭐가 더 맞다고 믿나요?', 2, '삶을 바라보는 방식은 경험에 따라 달라요.', '내가 만들어가는 삶과 이미 그려진 삶 중 뭘 믿고 싶나요?', '그렇게 믿게 된 계기가 있어요?'),
  (777, (SELECT id FROM interests WHERE code = 'VALUES'), '인간은 원래 착한 쪽인가요, 나쁜 쪽인가요?', 2, '사람을 보는 시선은 겪어온 경험에 따라 달라요.', '사람에 대한 믿음과 경계심, 뭐가 편안한가요?', '그렇게 생각하게 된 경험이 있어요?'),
  (778, (SELECT id FROM interests WHERE code = 'VALUES'), '성격은 타고난 본성과 자란 환경 중 뭐가 더 크게 좌우하나요?', 2, '성격의 뿌리를 어디서 찾는지는 사람마다 달라요.', '타고난 기질과 자란 환경, 뭐가 나를 설명하나요?', '그렇게 생각하게 된 계기가 있어요?'),
  (779, (SELECT id FROM interests WHERE code = 'VALUES'), '촘촘한 계획과 순간의 마음을 따르는 것 중 뭐가 더 나에게 맞나요?', 1, '계획과 즉흥, 둘 다 나름의 방식으로 삶을 채워가요.', '예측 가능한 안정감과 순간의 자유로움, 뭐가 편한가요?', '최근에 그 방식대로 해본 적 있어요?'),
  (780, (SELECT id FROM interests WHERE code = 'VALUES'), '미리 허락을 구하는 것과 일단 저지르는 것 중 뭐가 더 편한가요?', 1, '신중함과 과감함, 둘 다 상황에 따라 필요한 태도예요.', '확실히 하고 움직이기와 일단 시도하기, 뭐가 나다운가요?', '최근에 그렇게 해본 적 있어요?'),
  (781, (SELECT id FROM interests WHERE code = 'VALUES'), '다수를 위한 희생과 내 행복 중 뭐가 더 우선인가요?', 2, '나를 지키는 것과 남을 살피는 것, 둘 다 중요해요.', '나의 행복과 관계 속 역할 중 뭘 더 우선하나요?', '최근에 그런 상황 있었어요?'),
  (782, (SELECT id FROM interests WHERE code = 'VALUES'), '위험해도 자유로운 것과 안전을 위해 참는 것 중 뭐가 더 나에게 맞나요?', 2, '자유와 안전 사이의 균형은 누구에게나 어려운 고민이에요.', '마음껏 선택하는 자유와 흔들리지 않는 안정, 뭘 원하나요?', '요즘 나는 어느 쪽에 더 가까워요?'),
  (783, (SELECT id FROM interests WHERE code = 'VALUES'), '편안함을 추구하는 삶과 끊임없이 애쓰는 삶 중 뭐가 더 나다운가요?', 1, '편안함을 원하는 것도, 애쓰는 것도 다 나름의 이유가 있어요.', '지금의 여유와 앞으로의 성장 중 뭘 우선하고 싶나요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (784, (SELECT id FROM interests WHERE code = 'VALUES'), '한곳에 정착하는 삶과 계속 떠도는 삶 중 뭐가 더 어울리나요?', 1, '안정과 탐험, 둘 다 매력적인 삶의 방식이에요.', '익숙함이 주는 편안함과 낯섦이 주는 설렘, 뭘 원하나요?', '지금 삶은 어느 쪽에 더 가까워요?'),
  (785, (SELECT id FROM interests WHERE code = 'VALUES'), '무리에 자연스럽게 섞이는 것과 확실히 돋보이는 것 중 뭐가 더 편한가요?', 1, '어울림과 돋보임, 둘 다 관계에서 나름의 매력이 있어요.', '자연스럽게 섞이는 편안함과 눈에 띄는 존재감, 뭘 원하나요?', '평소 모임에서는 어느 쪽에 가까워요?'),
  (786, (SELECT id FROM interests WHERE code = 'VALUES'), '여러 분야를 두루 하는 것과 한 우물 파는 것 중 뭐가 더 나에게 맞나요?', 1, '넓이와 깊이, 둘 다 커리어에서 강점이 될 수 있어요.', '경험의 폭과 하나에 집중하는 전문성, 뭘 원하나요?', '지금 커리어는 어느 쪽에 가까워요?'),
  (787, (SELECT id FROM interests WHERE code = 'VALUES'), '학교에서 배운 것과 직접 부딪힌 경험 중 뭐가 더 크게 남나요?', 2, '배움의 방식은 사람마다 다르게 몸에 새겨져요.', '정리된 지식과 몸으로 겪은 깨달음, 뭐가 오래 남나요?', '가장 크게 배웠던 순간, 기억나요?'),
  (788, (SELECT id FROM interests WHERE code = 'VALUES'), '남의 조언을 받아들이는 것과 내 판단만 믿는 것 중 뭐가 더 나은가요?', 1, '조언을 대하는 태도는 나에 대한 믿음을 보여줘요.', '다른 시선을 받아들이는 유연함과 나를 믿는 확신, 뭘 지키나요?', '최근에 그렇게 해본 적 있어요?'),
  (789, (SELECT id FROM interests WHERE code = 'VALUES'), '관계 문제는 커플 상담과 자기계발서 중 뭐가 더 효과적인가요?', 1, '문제를 해결하는 방식은 사람마다 달라요.', '전문가의 도움과 스스로 찾는 답 중 뭘 믿고 싶나요?', '실제로 그런 방법 써본 적 있어요?'),
  (790, (SELECT id FROM interests WHERE code = 'VALUES'), '번 돈은 저축하는 것과 아낌없이 쓰는 것 중 뭐가 더 나다운가요?', 1, '돈을 대하는 태도는 가치관에 따라 달라요.', '미래를 위한 대비와 지금의 만족 중 뭘 중요히 보나요?', '요즘도 그 습관 그대로예요?'),
  (791, (SELECT id FROM interests WHERE code = 'VALUES'), '항상 솔직히 말하는 것과 돌려 말하는 것 중 뭐가 더 나에게 맞나요?', 2, '솔직함과 배려 사이 고민은 관계를 소중히 여긴다는 뜻이에요.', '있는 그대로의 진실과 배려, 뭘 우선하나요?', '최근에 그렇게 말해본 적 있어요?'),
  (792, (SELECT id FROM interests WHERE code = 'VALUES'), '사람을 만나면 일단 믿는 것과 의심하는 것 중 뭐가 더 나에게 맞나요?', 1, '사람을 대하는 태도는 겪어온 경험에 따라 만들어져요.', '먼저 믿는 마음과 스스로 지키는 경계심, 뭐가 편한가요?', '그 태도, 언제부터 그랬어요?'),
  (793, (SELECT id FROM interests WHERE code = 'VALUES'), '돈은 하나로 합치는 것과 각자 독립을 지키는 것 중 뭐가 더 편한가요?', 2, '돈을 나누는 방식은 관계에 대한 생각만큼이나 다양해요.', '하나로 합치는 것과 각자 영역 지키기, 뭘 원하나요?', '지금 관계에서도 그 방식이에요?'),
  (794, (SELECT id FROM interests WHERE code = 'VALUES'), '먼 미래를 계획하는 연애와 지금을 즐기는 연애 중 뭐가 더 편한가요?', 2, '미래를 그리는 속도는 사람마다 다르게 편안해요.', '장기적 계획의 안정감과 지금의 자유로움, 뭘 원하나요?', '지금 연애도 그 방식이에요?'),
  (795, (SELECT id FROM interests WHERE code = 'VALUES'), '열정 넘치는 삶과 평온한 삶 중 뭐가 더 끌리나요?', 2, '짜릿함과 평온함 둘 다 놓치기 아까워요.', '기복 있게 진하게, 아니면 잔잔하게 편안하게?', '지금 삶은 어느 쪽에 더 가까워요?'),
  (796, (SELECT id FROM interests WHERE code = 'VALUES'), '지금 가진 것에 만족하는 것과 더 원하는 것 중 뭐가 더 나다운가요?', 2, '만족과 욕심 사이에서 다들 흔들려요.', '지금 이 순간, 더 갖고 싶은 게 많나요?', '요즘 나는 어느 쪽에 더 가까워요?'),
  (797, (SELECT id FROM interests WHERE code = 'VALUES'), '역사에 이름을 남기는 삶과 행복한 평범함 중 뭐가 더 나은가요?', 2, '특별함과 평범한 행복 둘 다 소중해요.', '이름을 남기는 것과 편안한 것, 뭐가 끌리나요?', '요즘 그런 생각 해본 적 있어요?'),
  (798, (SELECT id FROM interests WHERE code = 'VALUES'), '지금 아니면 못 갈 것 같다면, 여행과 커리어 중 뭐가 더 끌리나요?', 2, '지금이냐 나중이냐, 타이밍 고민은 어려워요.', '지금 아니면 못 할 것 같은 건 어느 쪽인가요?', '그런 선택, 미뤄본 적 있어요?'),
  (799, (SELECT id FROM interests WHERE code = 'VALUES'), '늘 옳은 결정을 내리는 힘과 실수에서 빨리 배우는 힘 중 뭐가 더 필요한가요?', 2, '완벽한 판단력도 회복력도 다 갖고 싶어요.', '실수 안 하기와 빨리 딛고 일어서기, 뭐가 현실적인가요?', '돌아보면 나는 어느 쪽에 더 가까웠어요?'),
  (800, (SELECT id FROM interests WHERE code = 'VALUES'), '단 하나만 고를 수 있다면, 세상을 지키는 것과 나 자신을 지키는 것 중 뭐가 더 끌리나요?', 2, '이타심과 자기 보호 사이 고민은 쉽지 않아요.', '내 선택의 기준이 나인가요, 세상인가요?', '평소 내 선택도 그 기준이에요?'),
  (801, (SELECT id FROM interests WHERE code = 'VALUES'), '내 의도와 행동 중 뭐가 더 중요하게 평가받길 바라나요?', 2, '마음을 알아주길 바라는 것도 이해돼요.', '몰라준 의도와 인정 못 받은 행동, 뭐가 아쉬웠나요?', '남을 평가할 때 나는 어느 쪽을 더 봐요?'),
  (802, (SELECT id FROM interests WHERE code = 'VALUES'), '망해가는 회사의 사장과 잘나가는 대기업의 평사원 중 뭐가 더 편한가요?', 2, '책임의 무게와 안정감 사이 고민은 흔해요.', '내가 원하는 건 결정권인가요, 안정감인가요?', '지금 일에서 부족한 건 어느 쪽이에요?'),
  (803, (SELECT id FROM interests WHERE code = 'VALUES'), '외로운 천재와 단순해도 행복한 사람 중 누가 더 나에게 가깝나요?', 2, '인정받는 것과 마음 편한 것 둘 다 매력적이에요.', '내 행복의 기준은 이해인가요, 평온인가요?', '지금 나는 어느 쪽이 더 그리워요?'),
  (804, (SELECT id FROM interests WHERE code = 'VALUES'), '연봉이 두 배로 오르는 것과 1년 유급 휴가 중 뭐가 더 좋은가요?', 2, '돈과 시간 둘 다 놓치기 아까운 자원이에요.', '지금 더 부족한 건 돈인가요, 시간인가요?', '그렇게 되면 뭐부터 하고 싶어요?'),
  (805, (SELECT id FROM interests WHERE code = 'VALUES'), '일 안 해도 빠듯한 삶과 힘들어도 여유로운 삶 중 뭐가 더 나은가요?', 2, '자유로운 시간과 경제적 여유 다 아까워요.', '내 만족은 시간의 자유인가요, 돈의 여유인가요?', '지금 더 갈망하는 건 어느 쪽이에요?'),
  (806, (SELECT id FROM interests WHERE code = 'VALUES'), '혼자 일하는 것과 팀으로 일하는 것 중 뭐가 더 잘 맞나요?', 2, '혼자도 함께도 둘 다 존중받을 방식이에요.', '에너지가 채워지는 건 몰입인가요, 함께함인가요?', '실제로 어느 환경에서 더 잘 해냈어요?'),
  (807, (SELECT id FROM interests WHERE code = 'VALUES'), '야근 잦은 회사와 강도 높아도 칼퇴하는 회사 중 뭐가 더 끌리나요?', 2, '강도와 시간의 예측 가능성 둘 다 중요해요.', '하루를 지키는 건 강도인가요, 시간인가요?', '퇴근 후 삶, 나한테 얼마나 중요해요?'),
  (808, (SELECT id FROM interests WHERE code = 'VALUES'), '적은 월급에 좋아하는 일과 고액 연봉에 싫은 일 중 뭐가 더 만족스러운가요?', 2, '돈과 좋아하는 일 사이에서 고민되는 건 당연해요.', '더 절실한 건 여유인가요, 즐거움인가요?', '지금 일은 어느 쪽에 더 가까워요?'),
  (809, (SELECT id FROM interests WHERE code = 'VALUES'), '자유로운 프리랜서와 안정적인 직장인 중 누가 더 나에게 가깝나요?', 2, '자유와 안정 둘 다 포기하기 쉽지 않아요.', '불확실함을 견딜 만큼 자유가 소중한가요?', '지금 성향은 어느 쪽에 가까워요?'),
  (810, (SELECT id FROM interests WHERE code = 'VALUES'), '싫은 상사와 일하는 것과 친한 동료와 떨어지는 것 중 뭐가 더 나은가요?', 1, '누구와 일하느냐가 하루의 질을 좌우해요.', '내 기분을 더 좌우하는 건 상사인가요, 동료인가요?', '지금 직장에서 더 힘든 건 어느 쪽이에요?'),
  (811, (SELECT id FROM interests WHERE code = 'VALUES'), '평생 야근하는 것과 연봉이 동결되는 것 중 뭐가 더 견딜 만한가요?', 2, '시간과 돈 둘 다 잃고 싶지 않아요.', '지키고 싶은 건 저녁 있는 삶인가요, 오르는 연봉인가요?', '일에서 가장 아까운 건 어느 쪽이에요?'),
  (812, (SELECT id FROM interests WHERE code = 'VALUES'), '하루 종일 말하는 것과 듣기만 하는 것 중 뭐가 더 나다운가요?', 1, '말하는 것도 듣는 것도 다 에너지가 필요해요.', '표현할 때 힘이 나나요, 들을 때 편안한가요?', '평소 대화에서는 주로 어느 쪽이에요?'),
  (813, (SELECT id FROM interests WHERE code = 'VALUES'), '인생의 목적을 지금 아는 것과 서서히 깨닫는 것 중 뭐가 더 나은가요?', 2, '조급함도 여유도 다 자연스러워요.', '지금 확신이 필요한가요, 여유가 있나요?', '지금 나는 어느 쪽에 가까워요?'),
  (814, (SELECT id FROM interests WHERE code = 'VALUES'), '죽어서 기억되는 것과 살아서 사랑받는 것 중 뭐가 더 소중한가요?', 2, '넓은 기억과 깊은 사랑 다 삶의 의미예요.', '중요한 건 남겨질 이름인가요, 지금의 사랑인가요?', '요즘 더 갈망하는 건 어느 쪽이에요?'),
  (815, (SELECT id FROM interests WHERE code = 'VALUES'), '죽는 날짜를 아는 것과 모르는 것 중 뭐가 더 편안한가요?', 2, '아는 것도 모르는 것도 다 두려움과 안심을 줘요.', '확실함이 나를 편하게 하나요, 불안하게 하나요?', '그거 알면 삶이 달라질 것 같아요?'),
  (816, (SELECT id FROM interests WHERE code = 'VALUES'), '신중히 곱씹는 삶과 후회 없이 실수하는 삶 중 뭐가 더 나다운가요?', 2, '실수의 자유로움도 신중함의 안정감도 삶의 방식이에요.', '더 무거운 짐은 실수인가요, 못 한 후회인가요?', '지금까지 나는 어느 쪽에 가까웠어요?'),
  (817, (SELECT id FROM interests WHERE code = 'VALUES'), '100년 전 과거와 100년 후 미래 중 뭐가 더 궁금한가요?', 1, '과거도 미래도 다 호기심을 자극해요.', '그리운 건 뿌리인가요, 궁금한 건 가능성인가요?', '그 답, 내가 뭘 더 신경 쓰는지랑 관련있을까요?'),
  (818, (SELECT id FROM interests WHERE code = 'VALUES'), '다 기억하는 삶과 원할 때 잊는 삶 중 뭐가 더 좋은가요?', 2, '다 기억하고 싶은 마음도 잊고 싶은 순간도 자연스러워요.', '다 남겨두고 싶은가요, 필요할 때 지우고 싶은가요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (819, (SELECT id FROM interests WHERE code = 'VALUES'), '사람들의 속마음을 아는 것과 모르는 것 중 뭐가 더 편안한가요?', 2, '진실과 마음의 평화 둘 다 아까워요.', '진실을 감당할 준비가 되어 있나요?', '궁금한 누군가의 속마음, 정말 알고 싶어요?'),
  (820, (SELECT id FROM interests WHERE code = 'VALUES'), '남의 마음을 읽는 것과 내 마음을 나누는 것 중 뭐가 더 하고 싶나요?', 2, '알고 싶은 마음과 표현하고 싶은 마음 다 중요해요.', '더 답답한 건 표현 못함인가요, 모름인가요?', '지금 더 필요한 건 어느 쪽이에요?'),
  (821, (SELECT id FROM interests WHERE code = 'VALUES'), '두려움을 없애는 것과 강점을 키우는 것 중 뭐가 더 끌리나요?', 2, '약점을 지우는 것도 강점을 키우는 것도 성장이에요.', '더 자유롭게 하는 건 뭔가요?', '지금 나를 붙잡는 건 어느 쪽이에요?'),
  (822, (SELECT id FROM interests WHERE code = 'VALUES'), '내 무의식을 다 아는 것과 미스터리로 남겨두는 것 중 뭐가 더 끌리나요?', 2, '나를 다 알고 싶은 마음도 신비로 두고 싶은 마음도 있어요.', '나를 이해하는 게 자유를 주나요, 부담이 되나요?', '요즘 나 자신에 대해 가장 궁금한 게 뭐예요?'),
  (823, (SELECT id FROM interests WHERE code = 'VALUES'), '확고한 정체성과 계속 변하는 자유 중 뭐가 더 나에게 가깝나요?', 2, '확고한 정체성도 변화할 자유도 매력적이에요.', '안정감이 필요한가요, 변화의 여지가 필요한가요?', '지금 나는 나 자신을 얼마나 확신해요?'),
  (824, (SELECT id FROM interests WHERE code = 'VALUES'), '한 달을 슬퍼하고 달라지는 것과 1년을 무감각하게 사는 것 중 뭐가 더 나은가요?', 2, '고통을 견딘 성장도 무덤덤함도 이해돼요.', '나를 바꾸는 건 아픔인가요, 시간인가요?', '나를 가장 크게 바꾼 감정, 뭐였어요?'),
  (825, (SELECT id FROM interests WHERE code = 'VALUES'), '거짓말을 항상 알아채는 것과 전혀 못 알아채는 것 중 뭐가 더 나은가요?', 2, '다 아는 것도 모르는 것도 다 이유가 있어요.', '진실을 아는 게 관계를 지켜주나요, 힘들게 하나요?', '거짓말 알아챘을 때 어떻게 했어요?'),
  (826, (SELECT id FROM interests WHERE code = 'VALUES'), '아픈 진실을 말하는 것과 자비로운 거짓말을 하는 것 중 뭐가 더 옳은가요?', 2, '진실과 배려 사이 고민은 누구나 겪어요.', '상대에게 필요한 건 사실인가요, 위로인가요?', '최근에 그런 상황 있었어요?'),
  (827, (SELECT id FROM interests WHERE code = 'VALUES'), '평소 ''법을 어기더라도 불의에 맞서야 한다''고 생각하시나요, 아니면 ''부당해도 법은 지켜야 한다''고 생각하시나요?', 2, '규칙과 정의 사이 갈등은 답하기 어려워요.', '중요한 건 질서인가요, 옳음인가요?', '그 기준, 언제부터 그랬어요?'),
  (828, (SELECT id FROM interests WHERE code = 'VALUES'), '무고한 사람을 벌하는 것과 죄인을 풀어주는 것 중 뭐가 더 나은가요?', 2, '어느 쪽도 마음 무거운 딜레마예요.', '더 두려운 실수는 벌함인가요, 놓침인가요?', '그런 상상, 해본 적 있어요?'),
  (829, (SELECT id FROM interests WHERE code = 'VALUES'), '하지 않은 일로 인정받는 것과 억울하게 비난받는 것 중 뭐가 더 불편한가요?', 2, '말도 안 되는 인정도 비난도 둘 다 불편해요.', '더 괴로운 건 부풀린 칭찬인가요, 억울한 오해인가요?', '그런 상황이면 바로잡으려 할 것 같아요?'),
  (830, (SELECT id FROM interests WHERE code = 'VALUES'), '결과를 미리 아는 것과 모른 채 결정하는 것 중 뭐가 더 나은가요?', 2, '확신도 설렘도 다 자연스러운 바람이에요.', '중요한 건 안전한 확신인가요, 긴장감인가요?', '미리 알았으면 좋았을 선택, 있었어요?'),
  (831, (SELECT id FROM interests WHERE code = 'VALUES'), '경직돼도 공정한 법과 유연해서 가끔 불공정한 법 중 뭐가 더 옳다고 생각하나요?', 2, '원칙과 융통성의 균형은 관점마다 달라요.', '중요한 건 예외 없는 공정함인가요, 유연함인가요?', '그 기준, 평소에도 그래요?'),
  (832, (SELECT id FROM interests WHERE code = 'VALUES'), '의미 없는 큰 성공과 좋아하는 일로 이룬 성공 중 뭐가 더 끌리나요?', 2, '성공의 크기와 의미 둘 다 놓치기 아까워요.', '성공은 규모인가요, 만족감인가요?', '지금 내 일은 어느 쪽에 가까워요?'),
  (833, (SELECT id FROM interests WHERE code = 'VALUES'), '과거를 바꾸는 능력과 미래를 보는 능력 중 뭐가 더 갖고 싶나요?', 1, '바꾸고 싶은 마음과 알고 싶은 마음, 둘 다 자연스러워요.', '후회를 되돌리는 것과 미리 대비하는 것, 뭐가 끌리나요?', '지금 더 끌리는 건 어느 쪽이에요?'),
  (834, (SELECT id FROM interests WHERE code = 'VALUES'), '기억 없이 행복한 삶과 힘들어도 다 기억하는 삶 중 뭐가 더 끌리나요?', 2, '행복과 기억, 둘 다 포기하기 아까운 삶의 조각이에요.', '지금의 행복과 나를 이루는 기억, 뭐가 소중한가요?', '지금 나는 어느 쪽을 더 중요하게 여겨요?'),
  (835, (SELECT id FROM interests WHERE code = 'VALUES'), '우주의 비밀과 내 선택의 결과 중 뭐가 더 궁금한가요?', 1, '세상에 대한 호기심과 내 삶에 대한 궁금함, 둘 다 자연스러워요.', '바깥 세계와 내 앞날, 뭐가 더 절실한가요?', '평소에도 그런 게 더 궁금해요?'),
  (836, (SELECT id FROM interests WHERE code = 'VALUES'), '안 한 일로 기억되는 것과 한 일이 잊히는 것 중 뭐가 더 억울한가요?', 2, '오해로 남는 것과 인정받지 못하는 것, 둘 다 속상하죠.', '왜곡된 기억과 지워진 진실, 뭐가 더 견디기 힘든가요?', '그런 상황, 겪어본 적 있어요?'),
  (837, (SELECT id FROM interests WHERE code = 'VALUES'), '아이 같은 순수한 시선과 어른의 지혜 중 뭐가 더 갖고 싶나요?', 2, '순수함과 지혜, 둘 다 삶을 행복하게 하죠.', '때 묻지 않은 시선과 경험에서 오는 지혜, 뭘 원하나요?', '지금 나는 어느 쪽이 더 그리워요?'),
  (838, (SELECT id FROM interests WHERE code = 'VALUES'), '완벽해도 가짜인 삶과 평범해도 진짜인 삶 중 뭐가 더 나은가요?', 2, '완벽함과 진짜임 사이 고민, 누구에게나 낯설지 않아요.', '완벽하지만 가짜인 것과 부족해도 진짜인 것, 뭐가 중요한가요?', '지금 삶은 어느 쪽에 더 가까워요?'),
  (839, (SELECT id FROM interests WHERE code = 'VALUES'), '생각을 표현 못 하는 것과 조롱받는 것 중 뭐가 더 힘든가요?', 2, '말을 못 하게 되는 것과 비웃음당하는 것, 둘 다 상처가 돼요.', '표현 못 하는 답답함과 거절당하는 아픔, 뭐가 두려운가요?', '그런 상황, 겪어본 적 있어요?'),
  (840, (SELECT id FROM interests WHERE code = 'VALUES'), '하나를 잃어야 한다면, 재산을 잃는 것과 기억을 잃는 것 중 뭐가 덜 두렵나요?', 2, '돈을 잃는 것과 나를 이루는 기억을 잃는 것, 둘 다 두려워요.', '다시 쌓을 수 있는 것과 되찾을 수 없는 것, 뭐가 두려운가요?', '그거 잃는다고 생각하면 뭐가 제일 먼저 떠올라요?'),
  (841, (SELECT id FROM interests WHERE code = 'VALUES'), '거짓말을 알아채는 능력과 들키지 않는 능력 중 뭐가 더 탐나나요?', 2, '진실을 꿰뚫고 싶은 마음과 숨기고 싶은 마음, 둘 다 있죠.', '타인을 파악하는 힘과 나를 지키는 힘, 뭐가 필요한가요?', '요즘 둘 중 뭐가 더 신경쓰여요?'),
  (842, (SELECT id FROM interests WHERE code = 'VALUES'), '꿈꾸던 일과 진정한 사랑 중 뭐가 더 이루고 싶나요?', 2, '일의 성취와 사랑의 충만함, 둘 다 삶을 채우죠.', '성취감과 사람들과의 끈끈함 중 지금 더 필요한 건 뭔가요?', '지금 더 갈망하는 건 어느 쪽이에요?'),
  (843, (SELECT id FROM interests WHERE code = 'VALUES'), '평범한 사람들 틈에서 돋보이는 삶과 천재들 틈에서 평범한 삶 중 뭐가 더 끌리나요?', 2, '돋보이고 싶은 마음과 자극받고 싶은 마음, 둘 다 이해돼요.', '인정받는 편안함과 자극받는 긴장감, 뭘 원하나요?', '지금 있는 곳은 어느 쪽에 가까워요?'),
  (844, (SELECT id FROM interests WHERE code = 'VALUES'), '하나를 잃어야 한다면, 말하는 능력과 읽는 능력 중 뭐가 덜 아깝나요?', 2, '표현하는 힘과 받아들이는 힘, 둘 다 소중한 능력이죠.', '내 생각을 전하는 것과 세상을 이해하는 것, 뭘 포기 못 하나요?', '지금 뭘 더 자주 써요?'),
  (845, (SELECT id FROM interests WHERE code = 'VALUES'), '10년의 감옥살이와 20년의 혼수상태 중 뭐가 더 견딜 만한가요?', 2, '둘 다 시간을 잃는 상상이라 답하기 어렵죠.', '갇힌 의식의 시간과 사라진 시간, 뭐가 견딜 만한가요?', '상상만 해도 아찔하지 않아요?'),
  (846, (SELECT id FROM interests WHERE code = 'VALUES'), '웃긴 사람과 똑똑한 사람 중 누가 더 끌리나요?', 1, '웃음을 주는 매력과 똑똑함의 인정, 둘 다 매력적이죠.', '분위기를 살리는 것과 존재감을 드러내는 것, 뭘 원하나요?', '지금 곁에 그런 사람 있어요?'),
  (847, (SELECT id FROM interests WHERE code = 'VALUES'), '친절한 사람으로 남는 것과 똑똑한 사람으로 남는 것 중 뭐가 더 좋은가요?', 1, '따뜻한 사람과 똑똑한 사람, 둘 다 듣고 싶은 평가죠.', '따뜻하다는 인상과 똑똑하다는 인상, 뭘 원하나요?', '지금 나는 어느 쪽으로 더 기억되고 있어요?'),
  (848, (SELECT id FROM interests WHERE code = 'VALUES'), '다른 삶으로 태어나는 것과 기억을 지킨 채 환생하는 것 중 뭐가 더 하고 싶나요?', 2, '새로운 시작과 지금의 나를 잇는 것, 둘 다 매력 있죠.', '새로운 가능성과 지금의 나, 뭘 더 원하나요?', '지금 삶에 얼마나 만족해요?'),
  (849, (SELECT id FROM interests WHERE code = 'VALUES'), '속마음을 다 말하는 것과 평생 입을 다무는 것 중 뭐가 더 나은가요?', 2, '숨김없는 솔직함과 완전히 입을 다무는 것, 둘 다 극단적이죠.', '다 드러내는 부담과 못 전하는 답답함, 뭐가 힘든가요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (850, (SELECT id FROM interests WHERE code = 'VALUES'), '초능력이 생긴다면, 결정을 되돌리는 힘과 시간을 멈추는 힘 중 뭐가 더 탐나나요?', 1, '실수를 고치고 싶은 마음과 여유를 갖고 싶은 마음, 둘 다 있죠.', '지난 선택을 바로잡는 것과 순간을 늘리는 것, 뭐가 필요한가요?', '요즘 둘 중 뭐가 더 필요해요?'),
  (851, (SELECT id FROM interests WHERE code = 'VALUES'), '지금의 삶을 이어가는 것과 처음부터 다시 시작하는 것 중 뭐가 더 마음 편한가요?', 2, '쌓아온 것과 새로 시작할 가능성, 둘 다 고민되죠.', '지금의 나를 잇는 것과 다시 그리는 것, 뭘 원하나요?', '지금 삶에 얼마나 만족해요?'),
  (852, (SELECT id FROM interests WHERE code = 'VALUES'), '항상 이해받는 것과 인정받는 것 중 뭐가 더 좋은가요?', 2, '이해받고 싶은 마음과 인정받고 싶은 마음, 둘 다 소중하죠.', '마음을 알아주는 것과 능력을 알아주는 것, 뭐가 갈망되나요?', '지금 더 갈망하는 건 어느 쪽이에요?'),
  (853, (SELECT id FROM interests WHERE code = 'VALUES'), '죽는 시점과 죽는 방식 중 뭐가 더 알고 싶나요?', 2, '죽음을 미리 안다는 상상, 둘 다 무겁게 다가오죠.', '시간의 끝과 방식, 뭘 더 대비하고 싶나요?', '그거 알면 마음이 편해질 것 같아요?'),
  (854, (SELECT id FROM interests WHERE code = 'VALUES'), '항상 진실만 말하는 것과 남의 거짓말을 알아채는 것 중 뭐가 더 나은가요?', 2, '나를 정직하게 만드는 것과 남을 꿰뚫어보는 것, 다른 방식의 진실함이죠.', '내가 정직해지는 것과 남의 거짓을 아는 것, 뭘 원하나요?', '지금 더 필요한 건 어느 쪽이에요?'),
  (855, (SELECT id FROM interests WHERE code = 'VALUES'), '가장 행복할 날과 가장 불행할 날 중 뭐가 더 궁금한가요?', 2, '미리 아는 게 위로일지 부담일지 사람마다 달라요.', '기대하며 기다리는 것과 대비하며 기다리는 것, 뭐가 편한가요?', '미리 알면 마음이 편해질 것 같아요?'),
  (856, (SELECT id FROM interests WHERE code = 'VALUES'), '평온한 삶과 위험한 도전이 가득한 삶 중 뭐가 더 끌리나요?', 2, '안정과 자극, 원하는 게 시기마다 달라지죠.', '잔잔한 평온과 짜릿한 도전, 지금 뭐가 끌리나요?', '지금 더 끌리는 건 어느 쪽이에요?'),
  (857, (SELECT id FROM interests WHERE code = 'VALUES'), '야생에서 사는 것과 감옥에서 사는 것 중 뭐가 덜 힘든가요?', 2, '둘 다 자유롭지 못한 상상이라 답하기 어렵죠.', '거친 자유와 안전한 속박, 뭐가 견딜 만한가요?', '상상만 해도 답답하지 않아요?'),
  (858, (SELECT id FROM interests WHERE code = 'VALUES'), '모든 걸 너무 진지하게 받아들이는 사람과 아무것도 진지하게 여기지 않는 사람 중 어떤 쪽이 되고 싶나요?', 2, '지나친 진지함과 무심함, 둘 다 균형을 잃은 모습이죠.', '무거운 진지함과 가벼운 무심함, 뭘 경계하나요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (859, (SELECT id FROM interests WHERE code = 'VALUES'), '늘 관심의 중심이 되는 것과 아무도 모르게 지내는 것 중 뭐가 더 끌리나요?', 1, '주목받는 것과 조용히 지내는 것, 편한 정도가 다르죠.', '시선을 받는 즐거움과 자유로운 익명성, 뭘 원하나요?', '지금 나는 어느 쪽이 더 편해요?'),
  (860, (SELECT id FROM interests WHERE code = 'VALUES'), '수백 명이 깊이 읽는 것과 수백만 명이 스치듯 읽는 것 중 뭐가 더 뿌듯한가요?', 2, '깊이 남는 것과 널리 퍼지는 것, 창작자라면 둘 다 바라죠.', '소수의 진한 울림과 다수의 가벼운 스침, 뭘 원하나요?', '그런 반응, 실제로 겪어본 적 있어요?'),
  (861, (SELECT id FROM interests WHERE code = 'VALUES'), '가난해도 행복한 삶과 부유해도 불행한 삶 중 뭐가 더 나은가요?', 2, '돈과 행복, 둘 다 중요하지만 함께 안 갈 때도 있죠.', '물질적 풍요와 마음의 만족, 뭘 진짜 원하나요?', '지금 삶은 어느 쪽에 더 가까워요?'),
  (862, (SELECT id FROM interests WHERE code = 'VALUES'), '생명을 만드는 힘과 없애는 힘 중 뭐가 더 부담스럽나요?', 2, '둘 다 감당하기 무거운 힘이라 고민돼요.', '만드는 무게인가요 아니면 없애는 무게인가요?', '그런 상상, 해본 적 있어요?'),
  (863, (SELECT id FROM interests WHERE code = 'VALUES'), '완전히 이해받는 것과 있는 그대로라도 받아들여지는 것 중 뭐가 더 필요한가요?', 2, '이해와 받아들여짐, 둘 다 관계에서 우리가 바라는 것들이죠.', '설명이 필요한가요, 필요 없는 관계가 좋은가요?', '지금 관계에서 더 필요한 건 어느 쪽이에요?'),
  (864, (SELECT id FROM interests WHERE code = 'VALUES'), '후회 없이 사는 것과 두려움 없이 사는 것 중 뭐가 더 중요한가요?', 2, '둘 다 삶을 편하게 해줄 것 같아 고민되죠.', '지난 일의 미련인가요, 앞일의 두려움인가요?', '지금 더 붙잡고 있는 감정은 어느 쪽이에요?'),
  (865, (SELECT id FROM interests WHERE code = 'VALUES'), '도전과 안정 중 지금 뭐가 더 끌리나요?', 2, '삶의 방향은 시기마다 달라질 수 있어서 자연스러운 고민이에요.', '설렘의 활력인가요, 흔들리지 않는 편안함인가요?', '지금 삶의 리듬은 어느 쪽에 가까워요?'),
  (866, (SELECT id FROM interests WHERE code = 'VALUES'), '가짜 모습으로 사랑받는 것과 미움받아도 진짜 나로 사는 것 중 뭐가 더 끌리나요?', 2, '인정받고 싶은 마음과 나답고 싶은 마음, 둘 다 소중해요.', '사랑받는 게 우선인가요 아니면 진짜 나로 사는 게 우선인가요?', '지금 나는 어느 쪽에 더 가까워요?'),
  (867, (SELECT id FROM interests WHERE code = 'VALUES'), '완전한 자유와 무조건적인 권력 중 뭐가 더 갖고 싶나요?', 2, '무엇이든 될 수 있는 상상이라 답하기 쉽지 않은 질문이에요.', '남에게 미치는 힘인가요, 나를 위한 자유인가요?', '그거 갖게 되면 뭐부터 하고 싶어요?'),
  (868, (SELECT id FROM interests WHERE code = 'VALUES'), '과거의 모든 일과 미래의 모든 일 중 뭐가 더 궁금한가요?', 2, '지나간 일과 다가올 일, 둘 다 궁금해지는 게 사람 마음이에요.', '이해하고 싶은 건 과거인가요 아니면 대비하고 싶은 건 미래인가요?', '평소에도 그쪽이 더 궁금해요?'),
  (869, (SELECT id FROM interests WHERE code = 'VALUES'), '규칙이 하나도 없는 세상과 너무 많은 세상 중 뭐가 더 답답한가요?', 2, '자유와 질서 사이에서 무엇이 편한지는 사람마다 다르죠.', '예측 안 되는 자유가 불편한가요 아니면 꽉 짜인 관리가 불편한가요?', '지금 있는 환경은 어느 쪽에 가까워요?'),
  (870, (SELECT id FROM interests WHERE code = 'VALUES'), '세상을 바꾸려 애쓰는 것과 있는 그대로 받아들이는 것 중 뭐가 더 나에게 맞나요?', 2, '받아들임과 변화, 둘 다 삶을 대하는 나름의 지혜예요.', '지금에 만족하는 게 편한가요 아니면 나아지길 바라는 게 편한가요?', '평소 내 모습도 그래요?'),
  (871, (SELECT id FROM interests WHERE code = 'VALUES'), '완벽한 하루가 반복되는 삶과 굴곡 있는 진짜 삶 중 뭐가 더 나은가요?', 2, '완벽한 행복과 진짜 삶, 둘 다 매력적이지만 다른 걸 주죠.', '안정된 행복이 좋은가요 아니면 변화가 있는 진짜 삶이 좋은가요?', '요즘 하루하루는 어느 쪽에 더 가까워요?'),
  (872, (SELECT id FROM interests WHERE code = 'VALUES'), '선택지가 너무 많은 것과 하나의 길만 걷는 것 중 뭐가 더 답답한가요?', 2, '너무 많은 선택도, 선택이 없는 것도 둘 다 답답할 수 있어요.', '고민할 자유가 좋은가요 아니면 확실한 하나의 길이 좋은가요?', '결정할 때 나는 주로 어느 쪽 때문에 힘들어요?'),
  (873, (SELECT id FROM interests WHERE code = 'VALUES'), '과거 기억을 잃는 것과 새 기억을 못 만드는 것 중 뭐가 더 두렵나요?', 2, '과거와 미래, 어느 쪽을 잃어도 두려운 상상이에요.', '쌓아온 것들인가요, 앞으로의 가능성인가요?', '둘 중 어느 쪽이 더 두려워요?'),
  (874, (SELECT id FROM interests WHERE code = 'VALUES'), '완벽한 하루가 반복되는 삶과 굴곡 있는 진짜 삶 중 뭐가 더 나은가요?', 2, '완벽한 행복과 진짜 삶, 둘 다 매력적이지만 다른 걸 주죠.', '안정된 행복이 좋은가요 아니면 변화가 있는 진짜 삶이 좋은가요?', '요즘 하루하루는 어느 쪽에 더 가까워요?'),
  (875, (SELECT id FROM interests WHERE code = 'VALUES'), '선택지가 너무 많은 것과 하나의 길만 걷는 것 중 뭐가 더 답답한가요?', 2, '너무 많은 선택도, 선택이 없는 것도 둘 다 답답할 수 있어요.', '고민할 자유가 좋은가요 아니면 확실한 하나의 길이 좋은가요?', '결정할 때 나는 주로 어느 쪽 때문에 힘들어요?');

